const means=values=>{const a=values.filter(x=>typeof x==='number'&&Number.isFinite(x));return a.length?a.reduce((v,n)=>v+n,0)/a.length:null};
function median(values){const a=values.filter(Number.isFinite).sort((x,y)=>x-y);return a.length?(a[Math.floor((a.length-1)/2)]+a[Math.ceil((a.length-1)/2)])/2:null}
