function v2HomeData(){const c=activeClass(),ss=v2Scoped(),sub=subjects();let total=0,done=0;for(const s of ss)for(const x of sub){total++;if(Number.isFinite(score(s,x.id,meta.term)))done++}const today=now(),rec=data.attendance[today]||{},ids=ss.map(s=>s.id);const missingWork=data.assignments.reduce((n,a)=>n+ids.filter(id=>!a.completed.includes(id)).length,0);return {c,total,done,attDone:ids.length>0&&ids.every(id=>rec[id]),missingWork,today}}
views.home=function(){const h=v2HomeText[lang]||v2HomeText.en,d=v2HomeData(),fill=s=>s.replace('{c}',d.c?.name||'');const name=v2GreetingName(v2.teacherName,h);const manual=v2.homeTasks?.date===d.today?v2.homeTasks.ids:[];const tasks=[{id:'assess',text:fill(h.taskAssess),auto:d.total>0&&d.done===d.total,go:'quick'},{id:'attendance',text:fill(h.taskAttendance),auto:d.attDone,go:'attendance'},{id:'review',text:h.taskReview,auto:d.missingWork===0&&d.done===d.total,go:'missingData'}];const off=(314.16*(1-v2HomeRingPct/100)).toFixed(2);const actions=[['classes','users','tone-blue',h.manageClasses],['attendance','check','tone-green',h.takeAttendance],['addTask','calendarPlus','tone-purple',h.addTask],['quick','clipboard','tone-orange',h.quickAssess]];
return `<div class="cp-dash"><section class="cp-hero cp-anim" style="--i:0">${v2HomeWaves}<div class="cp-hero-text"><h2><span>${esc(h.hello)} ${esc(h.teacherTitle)} ${esc(name)}</span><span class="cp-wave" aria-hidden="true">👋</span><button type="button" class="cp-hero-edit" id="cpEditName" title="${esc(h.editName)}" aria-label="${esc(h.editName)}">${v2Svg('pencil')}</button></h2><p>${esc(h.heroSub)}</p></div><div class="cp-hero-art">${v2HomeArt}</div></section>
<div class="cp-actions">${actions.map((a,i)=>`<button type="button" class="cp-action cp-anim ${a[2]}" style="--i:${i+1}" data-fast="${a[0]}"><span class="cp-action-icon">${v2Svg(a[1])}</span><span>${esc(a[3])}</span></button>`).join('')}</div>
${v2.last?`<div class="v2-last cp-anim" style="--i:5"><div><b>${esc(v2tr('continue'))}</b><small style="display:block;color:var(--muted)">${esc(v2.last.subtitle||'')}</small></div><button class="btn" id="v2Resume">${esc(v2tr('resume'))}</button></div>`:''}
<div class="cp-dash-grid"><section class="cp-panel cp-anim" style="--i:5"><h3>${v2Svg('list')}${esc(h.todayTasks)}</h3><div class="cp-tasks">${tasks.map(x=>{const on=x.auto||manual.includes(x.id);return `<div class="cp-task ${on?'done':''}"><input type="checkbox" class="cp-check" data-task="${x.id}" ${on?'checked':''} ${x.auto?`disabled title="${esc(h.autoDone)}"`:''} aria-label="${esc(x.text)}"><button type="button" class="cp-task-text" data-togo="${x.go}">${esc(x.text)}</button><span class="cp-task-go" aria-hidden="true">${v2Svg('chevron')}</span></div>`}).join('')}</div></section>
<section class="cp-panel cp-anim" style="--i:6"><h3>${v2Svg('chart')}${esc(h.quickFollow)}</h3><div class="cp-follow"><div class="cp-ring" role="img" aria-label="${esc(h.completion)}: ${v2HomeRingPct}%"><svg viewBox="0 0 120 120" aria-hidden="true" focusable="false"><defs><linearGradient id="cpRingGrad" x1="0" y1="0" x2="1" y2="1"><stop offset="0" stop-color="#2CC08F"/><stop offset="1" stop-color="#168B8D"/></linearGradient></defs><circle class="cp-ring-track" cx="60" cy="60" r="50" fill="none" stroke-width="12"/><circle class="cp-ring-bar" cx="60" cy="60" r="50" fill="none" stroke-width="12" style="--off:${off}"/></svg><b id="cpRingValue" data-value="${v2HomeRingPct}">${v2HomeRingPct}%</b></div><div class="cp-follow-text"><strong>${esc(h.completion)}</strong></div></div></section></div>
<p class="footnote">${esc(v2tr('dataNote'))}</p></div>`};
function v2BindHome(){document.querySelectorAll('[data-fast]').forEach(b=>b.onclick=()=>{if(b.dataset.fast==='addTask'){v2SetPage('assignments');newAssignment()}else v2SetPage(b.dataset.fast)});document.querySelectorAll('[data-togo]').forEach(b=>b.onclick=()=>v2SetPage(b.dataset.togo));
document.querySelectorAll('[data-task]').forEach(cb=>cb.onchange=()=>{const today=now();if(v2.homeTasks?.date!==today)v2.homeTasks={date:today,ids:[]};const ids=new Set(v2.homeTasks.ids);if(cb.checked)ids.add(cb.dataset.task);else ids.delete(cb.dataset.task);v2.homeTasks.ids=[...ids];v2save();cb.closest('.cp-task').classList.toggle('done',cb.checked)});
const edit=$('#cpEditName');if(edit)edit.onclick=()=>{const h=v2HomeText[lang]||v2HomeText.en;modal(h.editName,`<form id="cpNameForm" class="v2-form"><label class="wide">${esc(h.nameLabel)}<input name="name" maxlength="60" value="${esc(v2GreetingName(v2.teacherName,h))}" required></label><div class="wide"><button class="btn">${esc(v2tr('save'))}</button></div></form>`);$('#cpNameForm').onsubmit=e=>{e.preventDefault();v2.teacherName=String(new FormData(e.target).get('name')).trim();v2save();closeModal();render()}};
const b=$('#v2Resume');if(b)b.onclick=()=>{if(v2.last.classId&&cl(v2.last.classId)){meta.activeClass=v2.last.classId;meta.term=v2.last.term;persist()}v2SetPage(v2.last.type)};
const ring=$('#cpRingValue');if(ring&&!matchMedia('(prefers-reduced-motion: reduce)').matches){const target=Number(ring.dataset.value)||0,start=performance.now()+300;const step=ts=>{const p=Math.max(0,Math.min(1,(ts-start)/1400));ring.textContent=Math.round(target*(1-Math.pow(1-p,3)))+'%';if(p<1&&ring.isConnected)requestAnimationFrame(step)};ring.textContent='0%';requestAnimationFrame(step)}}
views.semesters=function(){return `<section class="card"><div class="v2-cardhead"><div><h2>${esc(v2tr('termManager'))}</h2><p class="mini">${esc(v2tr('noCopy'))}</p></div><button class="btn" id="v2AddSemester">＋ ${esc(v2tr('createTerm'))}</button></div><div class="v2-tiles">${v2.semesters.map(x=>`<div class="v2-tile ${meta.term===x.id?'selected':''}"><strong>${esc(v2TermLabel(x.id))}</strong><span class="mini">${esc(x.start||'')} ${x.end?'— '+esc(x.end):''}</span><span class="badge">${esc(x.status==='closed'?v2tr('termClosed'):v2tr('termActiveState'))}</span><div class="v2-actions"><button class="btn sm" data-sem-select="${esc(x.id)}">${esc(v2tr('goto'))}</button><button class="btn secondary sm" data-sem-duplicate="${esc(x.id)}">${esc(v2tr('termDuplicate'))}</button><button class="btn secondary sm" data-sem-edit="${esc(x.id)}">${esc(tr('edit'))}</button></div></div>`).join('')}</div></section>`};
function v2BindSemesters(){const form=(existing=null,duplicate=false)=>{modal(duplicate?v2tr('termDuplicate'):existing?tr('edit'):v2tr('createTerm'),`<form id="v2SemesterForm" class="v2-form"><label class="wide">${esc(v2tr('termName'))}<input name="name" required maxlength="90" value="${duplicate?'':esc(existing?typeof existing.name==='string'?existing.name:v2TermLabel(existing.id):'')}"></label><label>${esc(tr('date'))} — ${esc(v2tr('termActiveState'))}<input name="start" type="date" value="${esc(existing?.start||'')}"></label><label>${esc(tr('date'))} — ${esc(v2tr('termClosed'))}<input name="end" type="date" value="${esc(existing?.end||'')}"></label><div class="wide v2-actions"><button class="btn">${esc(tr('save'))}</button><button class="btn secondary" type="button" id="v2CancelSemester">${esc(tr('cancel'))}</button></div></form><p class="mini">${esc(v2tr('noCopy'))}</p>`);$('#v2CancelSemester').onclick=closeModal;$('#v2SemesterForm').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target);const name=String(f.get('name')).trim();const start=String(f.get('start')),end=String(f.get('end'));if(start&&end&&start>end){message(v2tr('termDates'));return}if(existing&&!duplicate){existing.name={he:name,ar:name,en:name};existing.start=start;existing.end=end}else{const id='term-'+safeId();v2.semesters.push({id,name:{he:name,ar:name,en:name},start,end,status:'active'});meta.term=id;meta.reportTerm=id;meta.chartTerm=id}v2save();persist();closeModal();render()}};$('#v2AddSemester').onclick=()=>form();document.querySelectorAll('[data-sem-select]').forEach(b=>b.onclick=()=>{meta.term=b.dataset.semSelect;meta.reportTerm=meta.term;meta.chartTerm=meta.term;persist();render()});document.querySelectorAll('[data-sem-edit]').forEach(b=>b.onclick=()=>form(v2.semesters.find(x=>x.id===b.dataset.semEdit)));document.querySelectorAll('[data-sem-duplicate]').forEach(b=>b.onclick=()=>form(v2.semesters.find(x=>x.id===b.dataset.semDuplicate),true))}
views.quick=function(){const ss=v2Scoped();const chosen=v2.quickSubject;if(!ss.length)return `<section class="card">${esc(v2tr('noStudents'))}</section>`;const existing=v2.drafts[`${meta.activeClass}|${meta.term}|${chosen}`]||{};return `<section class="card"><div class="v2-cardhead"><div><h2>${esc(v2tr('quickAssess'))}</h2><p class="mini">${esc(v2tr('quickSub'))}</p></div><button class="btn secondary sm" id="v2AddSubjectQuick">＋ ${esc(tr('addSubject'))}</button></div><div class="v2-form"> <label>${esc(v2tr('subject'))}${sel('v2QSub',subjects().map(s=>[s.id,sName(s.id)]),chosen)}</label><label>${esc(v2tr('evalType'))}${sel('v2QType',[['test',v2tr('test')],['project',v2tr('project')],['participation',v2tr('participation')]],v2.quickType)}</label></div><div class="tablewrap" style="margin-top:18px"><table><thead><tr><th>${esc(v2tr('student'))}</th><th>${esc(v2tr('scoreMissing'))}</th><th>${esc(v2tr('notes'))}</th></tr></thead><tbody>${ss.map(s=>`<tr><td><b>${esc(s.name)}</b></td><td><input class="v2QScore" style="width:100px" inputmode="decimal" type="number" min="0" max="100" data-student="${s.id}" placeholder="—" value="${esc(existing[s.id]?.grade??'')}"></td><td><input class="v2QNote" data-student="${s.id}" placeholder="${esc(tr('notes'))}" value="${esc(existing[s.id]?.notes??'')}"></td></tr>`).join('')}</tbody></table></div><div class="v2-actions"><button class="btn" id="v2SaveGrades">${esc(v2tr('saveGrades'))}</button><button class="btn secondary" id="v2ExportGradeTemplate">${esc(v2tr('exportTemplate'))}</button><button class="btn secondary" id="v2ImportGradeTemplate">${esc(v2tr('importScores'))}</button><input type="file" id="v2GradeFile" accept=".csv,text/csv" hidden></div><p class="footnote" id="v2DraftState">${esc(v2tr('gradeScale'))} ${esc(v2tr('templateHints'))}</p></section>`};
function v2BindQuick(){const setDraft=()=>{const key=`${meta.activeClass}|${meta.term}|${v2.quickSubject}`;const snap={};document.querySelectorAll('.v2QScore').forEach(el=>{snap[el.dataset.student]={grade:el.value,notes:document.querySelector(`.v2QNote[data-student="${el.dataset.student}"]`)?.value||''}});v2.drafts[key]=snap;v2LeaveDraft('quick',`${v2tr('quickAssess')} — ${sName(v2.quickSubject)} · ${activeClass()?.name||''}`);$('#v2DraftState').textContent=v2tr('draftSaved')};document.querySelectorAll('.v2QScore,.v2QNote').forEach(el=>el.addEventListener('input',setDraft));$('#v2QSub').onchange=e=>{v2.quickSubject=e.target.value;v2save();render()};$('#v2QType').onchange=e=>{v2.quickType=e.target.value;v2save()};$('#v2AddSubjectQuick').onclick=addSubjectModal;$('#v2SaveGrades').onclick=()=>{const items=[...document.querySelectorAll('.v2QScore')].map(el=>{const val=el.value.trim();return {id:Number(el.dataset.student),grade:val===''?null:Number(val),notes:document.querySelector(`.v2QNote[data-student="${el.dataset.student}"]`)?.value||''}});if(items.some(x=>x.grade!==null&&(!Number.isFinite(x.grade)||x.grade<0||x.grade>100))){message(v2tr('gradeScale'));return}let changed=0;items.forEach(x=>{if(x.grade==null)return;meta.evaluations[x.id]??=[];meta.evaluations[x.id].push({id:safeId(),subjectId:v2.quickSubject,term:meta.term,grade:x.grade,notes:x.notes,date:now(),kind:v2.quickType});changed++});persist();delete v2.drafts[`${meta.activeClass}|${meta.term}|${v2.quickSubject}`];v2.last=null;v2save();message(`${v2tr('saved')} · ${changed}`);render()};$('#v2ExportGradeTemplate').onclick=()=>csvDownload([["Student","Score","Notes"],...v2Scoped().map(s=>[s.name,'',''])],'class_pulse_grade_template');$('#v2ImportGradeTemplate').onclick=()=>$('#v2GradeFile').click();$('#v2GradeFile').onchange=async e=>{try{const text=await e.target.files[0].text();const lines=text.replace(/^\uFEFF/,'').trim().split(/\r?\n/);let rows=lines.slice(1).map(l=>l.split(',').map(x=>x.replace(/^"|"$/g,'').trim()));for(const row of rows){let student=v2Scoped().find(s=>s.name.toLocaleLowerCase()===row[0]?.toLocaleLowerCase());if(!student)continue;let field=document.querySelector(`.v2QScore[data-student="${student.id}"]`);if(field)field.value=row[1]||'';const note=document.querySelector(`.v2QNote[data-student="${student.id}"]`);if(note)note.value=row[2]||''}setDraft();message(v2tr('draftSaved'))}catch(err){message(err.message)}}}
views.missingData=function(){let ss=v2Scoped();return `<section class="card"><div class="v2-cardhead"><div><h2>${esc(v2tr('missingCenter'))}</h2><p class="mini">${esc(v2tr('studentsPending'))} · ${esc(v2TermLabel(meta.term))}</p></div><button class="btn" id="v2MissingQuick">${esc(v2tr('quickAssess'))}</button></div>${subjects().map(sub=>{const missing=ss.filter(s=>score(s,sub.id,meta.term)==null);return `<div class="v2-workitem"><div><b>${esc(sName(sub.id))}</b><small>${missing.length?missing.map(s=>s.name).join(' · '):v2tr('saved')}</small></div><button class="btn secondary sm" data-missing-sub="${esc(sub.id)}">${missing.length} ${esc(v2tr('missingCount'))}</button></div>`}).join('')}</section>`};
function v2BindMissing(){$('#v2MissingQuick').onclick=()=>v2SetPage('quick');document.querySelectorAll('[data-missing-sub]').forEach(el=>el.onclick=()=>{v2.quickSubject=el.dataset.missingSub;v2save();v2SetPage('quick')})}
// Original student records and existing CRUD are kept. This adds direct navigation and semester context.
function v2DecorateStudents(){document.querySelectorAll('#studentResults tbody tr').forEach(r=>{const id=r.querySelector('button[onclick*="editStudent"]')?.getAttribute('onclick')?.match(/\d+/)?.[0];if(!id)return;const s=data.students.find(x=>String(x.id)===id);if(!s)return;const cell=r.querySelector('td');if(cell)cell.innerHTML=`<button class="v2-studentlink" data-open-profile="${id}">${esc(s.name)}</button>`});document.querySelectorAll('[data-open-profile]').forEach(b=>b.onclick=()=>v2SetPage('studentProfile',b.dataset.openProfile))}
function v2EnrichProfile(){const target=$('#view');if(!target)return;const s=data.students.find(x=>x.id===studentFocus);if(!s)return;const b=document.createElement('div');b.className='v2-actions';b.innerHTML=`<button class="btn secondary" id="v2ProfileBack">← ${esc(v2tr('goBack'))}</button><button class="btn secondary" id="v2ProfileQuick">${esc(v2tr('quickAssess'))}</button>`;const oldBack=$('#backStudents');if(oldBack)oldBack.onclick=()=>v2SetPage('students');target.prepend(b);$('#v2ProfileBack').onclick=()=>history.length>1?history.back():v2SetPage('students');$('#v2ProfileQuick').onclick=()=>v2SetPage('quick')}
const v2SectionIds=['cover','stats','grades','topStudents','chart','attendance','trend','notes','next'];
const v2SectionLabel=id=>v2tr('section'+id[0].toUpperCase()+id.slice(1));
const v2CurrentReport=()=>{v2.report.classId=meta.reportClass;v2.report.term=meta.reportTerm;return v2.report};
function v2ReportData(){const r=v2CurrentReport(),c=cl(r.classId)||activeClass(),students=studentsIn(c),term=r.term;const perSubject=subjects().map(sub=>({id:sub.id,name:sName(sub.id),value:means(students.map(s=>score(s,sub.id,term))),count:students.filter(s=>Number.isFinite(score(s,sub.id,term))).length}));const gradeScores=students.map(s=>score(s,'math',term)).filter(Number.isFinite);const selectedSubject=r.chartSubject||'math',availableSubjects=subjects(),chartSubjects=selectedSubject==='all'?availableSubjects:[availableSubjects.find(sub=>sub.id===selectedSubject)||availableSubjects[0]],chartSubjectName=selectedSubject==='all'?tr('allSubjects'):sName(chartSubjects[0]?.id||'math'),chartScores=students.flatMap(student=>chartSubjects.map(sub=>score(student,sub.id,term))).filter(Number.isFinite),counts=ranges.map(x=>chartScores.filter(v=>v>=x.min&&v<x.max).length),topStudents=students.map((student,index)=>({name:student.name,average:means(subjects().map(sub=>score(student,sub.id,term))),order:index})).filter(student=>Number.isFinite(student.average)).sort((a,b)=>b.average-a.average||a.order-b.order).slice(0,3).map((student,index)=>({...student,rank:index+1}));return{r,c,students,term,perSubject,gradeScores,chartScores,chartSubjectName,counts,topStudents,classAvg:means(perSubject.map(x=>x.value)),attendance:means(students.map(s=>attPct(s.id))),completion:means(students.map(s=>completion(s.id)))}}
const v2TopStudentsMarkup=students=>students?.length?`<div class="v2-top-students">${students.map((student,index)=>`<article class="v2-top-student rank-${index+1}" data-top-student-rank="${index+1}"><span class="v2-top-medal" aria-hidden="true">${['🏆','🥈','🥉'][index]}</span><small>${esc(v2tr(['rankFirst','rankSecond','rankThird'][index]))}</small><strong>${esc(student.name)}</strong><span class="v2-top-average">${fmt(student.average)}<small>${esc(v2tr('topAverage'))}</small></span></article>`).join('')}</div>`:`<p class="v2-top-empty">${esc(v2tr('noTopStudents'))}</p>`;
function v2ReportPreview(){const {r,c,students,term,perSubject,gradeScores,chartScores,chartSubjectName,counts,classAvg,attendance,completion:classCompletion}=v2ReportData();const person=students.find(x=>String(x.id)===String(r.studentId))||students[0];const parentMode=r.audience==='parent',title=r.title?.trim()||tr('reportTitle'),detail=parentMode?(person?.name||''):`${c?.name||''} · ${v2TermLabel(term)}`;const allow=r.sections||[];const section=(id,body)=>allow.includes(id)?`<section class="v2-report-section" data-report-section="${id}"><h2>${esc(v2SectionLabel(id))}</h2>${body}</section>`:'';const subjectRows=parentMode?perSubject.map(x=>({...x,value:person?score(person,x.id,term):null})):perSubject;const statsBody=parentMode?`<div class="report-kpis"><div><b>${esc(person?.name||'—')}</b><small>${esc(v2tr('student'))}</small></div><div><b>${fmt(means(subjectRows.map(x=>x.value)))}</b><small>${esc(tr('avg'))}</small></div><div><b>${person?attPct(person.id):'—'}%</b><small>${esc(tr('attendance'))}</small></div></div>`:`<div class="report-kpis"><div><b>${students.length}</b><small>${esc(tr('total'))}</small></div><div><b>${fmt(classAvg)}</b><small>${esc(tr('avg'))}</small></div><div><b>${gradeScores.length}</b><small>${esc(tr('evaluated'))}</small></div></div>`;
const gradeHtml=subjectRows.map(x=>`<div class="bars-row"><span>${esc(x.name)}</span><div class="bars-track"><div class="bars-fill" style="width:${Number.isFinite(x.value)?Math.max(0,Math.min(100,x.value)):0}%"></div></div><b>${fmt(x.value)}</b></div>`).join('');const donutHtml=`<div style="display:flex;gap:18px;flex-wrap:wrap;align-items:center"><div style="width:125px;height:125px;flex:0 0 auto">${donut({total:chartScores.length,counts},chartSubjectName).replace('cp-donut-wrapper','cp-donut-wrapper v2-small-donut')}</div><div>${ranges.map((range,i)=>`<div style="font-size:12px"><span style="display:inline-block;background:${range.color};width:9px;height:9px;border-radius:100%;margin-inline-end:5px"></span>${range.label}: ${counts[i]}</div>`).join('')}</div></div>`;
return `<article id="v2ReportDocument" class="v2-report-paper ${r.orientation==='landscape'?'landscape':''}" lang="${lang}" dir="${transText()}">${allow.includes('cover')?`<div class="report-head"><div style="font-size:11px;letter-spacing:2px">CLASS PULSE · ${esc(v2TermLabel(term))}</div><h1>${esc(title)}</h1><div>${esc(c?.school||'')} · ${esc(detail)}</div><div style="font-size:11px;margin-top:11px">${new Date().toLocaleDateString(lang==='en'?'en-US':lang==='ar'?'ar-IL':'he-IL')}</div></div>`:''}${section('stats',statsBody)}${section('grades',gradeHtml||tr('norecord'))}${!parentMode?section('chart',donutHtml):''}${section('attendance',`<p>${esc(tr('attendance'))}: ${parentMode?person?attPct(person.id):'—':fmt(attendance)}% · ${esc(tr('completion'))}: ${parentMode?person?completion(person.id):'—':fmt(classCompletion)}%</p>`)}${!parentMode?section('trend',`<p>${esc(v2TermLabel('1'))}: ${fmt(analyticsFor(c.id,'math','1').average)} · ${esc(v2TermLabel('2'))}: ${fmt(analyticsFor(c.id,'math','2').average)}</p>`):''}${section('notes',`<p style="white-space:pre-wrap;line-height:1.7">${esc(r.notes||tr('dataScope'))}</p>`)}${section('next',`<p>${esc(tr('privacyNote'))}</p>`)}<div class="report-bottom">CLASS PULSE · ${esc(v2TermLabel(term))} · ${esc(v2tr('dataNote'))}</div></article>`}
const v2ReportPreviewBase=v2ReportPreview;
v2ReportPreview=function(){const{r,topStudents}=v2ReportData(),html=v2ReportPreviewBase();if(r.audience==='parent'||!r.sections.includes('topStudents'))return html;const section=`<section class="v2-report-section" data-report-section="topStudents"><h2>${esc(v2SectionLabel('topStudents'))}</h2>${v2TopStudentsMarkup(topStudents)}</section>`;return html.replace('<div class="report-bottom">',`${section}<div class="report-bottom">`)};
views.reports=function(){const r=v2CurrentReport();if(!Array.isArray(r.sections))r.sections=[...v2SectionIds];else r.sections=r.sections.filter(id=>v2SectionIds.includes(id));const step=Math.max(0,Math.min(3,v2.stage));const options=[[0,'principal'],[0,'staff'],[0,'parent']];return `<div class="v2-steps">${[0,1,2,3].map(i=>`<button class="v2-step ${i===step?'active':''}" data-v2step="${i}">${i+1}. ${esc(v2tr('reportStep'+(i+1)))}</button>`).join('')}</div><div class="v2-report-layout"><section class="card"><h2 style="margin-bottom:16px">${esc(v2tr('reportStep'+(step+1)))}</h2><div class="v2-form">${mfield(tr('selectClass'),sel('v2RepClass',meta.classes.map(c=>[c.id,c.name]),r.classId))}${mfield(v2tr('selectTerm'),sel('v2RepTerm',v2.semesters.map(x=>[x.id,v2TermLabel(x.id)]),r.term))}</div><div style="margin-top:16px">${step===0?`<div class="stack">${['principal','staff','parent'].map(key=>`<label class="v2-choice"><input type="radio" name="v2Audience" value="${key}" ${r.audience===key?'checked':''}><strong>${esc(v2tr(key))}</strong></label>`).join('')}</div>${r.audience==='parent'?`<label class="field" style="margin-top:12px">${esc(v2tr('student'))}${sel('v2RepStudent',studentsIn(cl(r.classId)||activeClass()).map(s=>[String(s.id),s.name]),String(r.studentId||studentsIn(cl(r.classId)||activeClass())[0]?.id||''))}</label>`:''}`:step===1?`<h3 style="font-size:14px;margin:12px 0">${esc(v2tr('reportSections'))}</h3><div id="v2SectionEditor">${r.sections.map((id,i)=>`<div class="v2-reorder"><input type="checkbox" checked data-enable="${id}" aria-label="${esc(v2SectionLabel(id))}"><span>${esc(v2SectionLabel(id))}</span><button data-move="up" data-index="${i}" title="${esc(v2tr('moveUp'))}">↑</button><button data-move="down" data-index="${i}" title="${esc(v2tr('moveDown'))}">↓</button></div>`).join('')}</div><div class="v2-actions"><button class="btn secondary sm" id="v2RestoreSection">＋ ${esc(v2tr('reportSections'))}</button></div>`:step===2?`<div class="stack"><label class="field">${esc(v2tr('format'))}${sel('v2RepFormat',[['pdf','PDF'],['pptx','PowerPoint']],r.format)}</label><label class="field">${esc(v2tr('orientation'))}${sel('v2RepOrientation',[['portrait',v2tr('portrait')],['landscape',v2tr('landscape')]],r.orientation)}</label><label class="field">${esc(v2tr('extraTitle'))}<input id="v2RepTitle" maxlength="180" value="${esc(r.title||'')}"></label><label class="field">${esc(v2tr('extraNotes'))}<textarea id="v2RepNotes">${esc(r.notes||'')}</textarea></label></div>`:`<p class="mini">${esc(v2tr('printExplanation'))}</p><div class="v2-actions"><button class="btn" id="v2ReportDownload">↓ ${esc(v2tr('download'))} ${r.format.toUpperCase()}</button><button class="btn secondary" id="v2Slides">${esc(v2tr('slidesMode'))}</button><button class="btn secondary" id="v2SaveReport">${esc(v2tr('reportSave'))}</button></div>`}</div><div class="v2-actions" style="margin-top:20px"><button class="btn secondary" id="v2RepBack" ${step===0?'disabled':''}>${esc(v2tr('back'))}</button><button class="btn" id="v2RepNext" ${step===3?'disabled':''}>${esc(v2tr('forward'))}</button></div><p class="footnote">${esc(v2tr('dataNote'))}</p></section><div><div class="v2-cardhead"><h2>${esc(v2tr('preview'))}</h2><span class="badge">${r.orientation==='portrait'?v2tr('portrait'):v2tr('landscape')} · ${r.format.toUpperCase()}</span></div>${v2ReportPreview()}</div></div>`};
function v2BindStudio(){const r=v2CurrentReport();document.querySelectorAll('[data-v2step]').forEach(b=>b.onclick=()=>{v2.stage=Number(b.dataset.v2step);v2save();render()});$('#v2RepBack').onclick=()=>{v2.stage=Math.max(0,v2.stage-1);v2save();render()};$('#v2RepNext').onclick=()=>{v2.stage=Math.min(3,v2.stage+1);v2save();render()};$('#v2RepClass').onchange=e=>{r.classId=meta.reportClass=e.target.value;meta.activeClass=e.target.value;r.studentId=null;persist();v2save();render()};$('#v2RepTerm').onchange=e=>{r.term=meta.reportTerm=e.target.value;meta.term=e.target.value;persist();v2save();render()};document.querySelectorAll('[name="v2Audience"]').forEach(el=>el.onchange=()=>{r.audience=el.value;if(r.audience==='parent'){r.sections=r.sections.filter(id=>!['chart','trend'].includes(id));r.studentId=studentsIn(cl(r.classId)||activeClass())[0]?.id||null}else{for(const id of ['chart','trend'])if(!r.sections.includes(id))r.sections.push(id)}v2save();render()});const student=$('#v2RepStudent');if(student)student.onchange=e=>{r.studentId=e.target.value;v2save();render()};document.querySelectorAll('[data-move]').forEach(b=>b.onclick=()=>{let i=+b.dataset.index,j=i+(b.dataset.move==='up'?-1:1);if(j<0||j>=r.sections.length)return;[r.sections[i],r.sections[j]]=[r.sections[j],r.sections[i]];v2save();render()});document.querySelectorAll('[data-enable]').forEach(el=>el.onchange=()=>{if(!el.checked)r.sections=r.sections.filter(id=>id!==el.dataset.enable);v2save();render()});let restore=$('#v2RestoreSection');if(restore)restore.onclick=()=>{const avail=v2SectionIds.filter(x=>!r.sections.includes(x));if(!avail.length)return;modal(v2tr('reportSections'),`<div class="stack">${avail.map(x=>`<button class="btn secondary" data-addsec="${x}">${esc(v2SectionLabel(x))}</button>`).join('')}</div>`);document.querySelectorAll('[data-addsec]').forEach(b=>b.onclick=()=>{r.sections.push(b.dataset.addsec);v2save();closeModal();render()})};const fmtInput=$('#v2RepFormat');if(fmtInput)fmtInput.onchange=e=>{r.format=e.target.value;v2save();render()};const orInput=$('#v2RepOrientation');if(orInput)orInput.onchange=e=>{r.orientation=e.target.value;v2save();render()};const titleInput=$('#v2RepTitle');if(titleInput)titleInput.oninput=e=>{r.title=e.target.value;v2LeaveDraft('reports',r.title||v2tr('newReport'));document.querySelector('#v2ReportDocument .report-head h1')?.replaceChildren(document.createTextNode(r.title||tr('reportTitle')))};const notesInput=$('#v2RepNotes');if(notesInput)notesInput.oninput=e=>{r.notes=e.target.value;v2LeaveDraft('reports',r.title||v2tr('newReport'))};const dl=$('#v2ReportDownload');if(dl)dl.onclick=()=>r.format==='pdf'?v2PrintPDF():v2PPTXExport();const slide=$('#v2Slides');if(slide)slide.onclick=v2Present;const save=$('#v2SaveReport');if(save)save.onclick=()=>{v2.library.unshift({id:safeId(),name:r.title||`${tr('reportTitle')} · ${activeClass()?.name}`,report:structuredClone(r),date:new Date().toLocaleDateString()});v2.last=null;v2save();message(v2tr('saved'))}}
function v2PrintPDF(){const area=document.getElementById('v2PrintArea')||document.createElement('div');area.id='v2PrintArea';area.innerHTML=v2ReportPreview();document.body.append(area);const style=document.getElementById('v2PageStyle')||document.createElement('style');style.id='v2PageStyle';style.textContent=`@page { size: A4 ${v2.report.orientation==='landscape'?'landscape':'portrait'}; margin: 12mm; }`;document.head.append(style);document.body.classList.add('v2-printing');const done=()=>{document.body.classList.remove('v2-printing');window.removeEventListener('afterprint',done)};window.addEventListener('afterprint',done);setTimeout(()=>window.print(),60)}
function v2SlideRecords(){const d=v2ReportData(),{r,c,students,term,perSubject,counts,gradeScores,attendance,completion}=d;const chosen=students.find(s=>String(s.id)===String(r.studentId))||students[0],isParent=r.audience==='parent';const title=r.title?.trim()||tr('reportTitle');const records=[];if(r.sections.includes('cover'))records.push({title,body:`${c?.school||''}\n${isParent?chosen?.name||'':c?.name||''} · ${v2TermLabel(term)}`,kind:'cover'});if(r.sections.includes('stats'))records.push({title:v2SectionLabel('stats'),body:isParent?`${chosen?.name||''}\n${tr('avg')}: ${fmt(means(perSubject.map(s=>chosen?score(chosen,s.id,term):null)))}`:`${tr('total')}: ${students.length}\n${tr('avg')}: ${fmt(d.classAvg)}\n${tr('evaluated')}: ${gradeScores.length}`,kind:'stats'});if(r.sections.includes('grades'))records.push({title:v2SectionLabel('grades'),body:perSubject.map(s=>`${s.name}: ${fmt(isParent?(chosen?score(chosen,s.id,term):null):s.value)}${!isParent?' ('+s.count+')':''}`).join('\n'),kind:'grades',subs:perSubject});if(!isParent&&r.sections.includes('chart'))records.push({title:v2SectionLabel('chart'),body:ranges.map((x,i)=>`${x.label}: ${counts[i]}`).join('\n'),kind:'chart',counts});if(r.sections.includes('attendance'))records.push({title:v2SectionLabel('attendance'),body:`${tr('attendance')}: ${fmt(isParent?chosen?attPct(chosen.id):null:attendance)}%\n${tr('completion')}: ${fmt(isParent?chosen?completion(chosen.id):null:completion)}%`,kind:'attendance'});if(!isParent&&r.sections.includes('trend'))records.push({title:v2SectionLabel('trend'),body:`${v2TermLabel('1')}: ${fmt(analyticsFor(c.id,'math','1').average)}\n${v2TermLabel('2')}: ${fmt(analyticsFor(c.id,'math','2').average)}`,kind:'trend'});if(r.sections.includes('notes'))records.push({title:v2SectionLabel('notes'),body:r.notes||tr('dataScope'),kind:'notes'});if(r.sections.includes('next'))records.push({title:v2SectionLabel('next'),body:tr('privacyNote'),kind:'next'});if(!records.length)records.push({title,body:tr('none'),kind:'empty'});return records}
function v2Present(){const records=v2SlideRecords();let current=0;const overlay=document.createElement('div');overlay.className='v2-slideview';overlay.id='v2SlideView';overlay.innerHTML=`<div><div class="v2-slideframe" dir="${transText()}"><div class="v2-slidebrand">CLASS PULSE · PROGRESS CIRCLE</div><h2 id="v2SlideTitle"></h2><p id="v2SlideText"></p></div><div class="v2-slidecontrols"><button id="v2SlidePrev">${esc(v2tr('prevSlide'))}</button><span id="v2SlideCount"></span><button id="v2SlideNext">${esc(v2tr('nextSlide'))}</button><button id="v2SlideExit">${esc(v2tr('closeSlides'))}</button></div></div>`;document.body.append(overlay);const update=()=>{$('#v2SlideTitle').textContent=records[current].title;$('#v2SlideText').textContent=records[current].body;$('#v2SlideCount').textContent=`${current+1} / ${records.length}`;$('#v2SlidePrev').disabled=current===0;$('#v2SlideNext').disabled=current===records.length-1};const exit=()=>{overlay.remove();document.removeEventListener('keydown',keys)};const previous=()=>{current=Math.max(0,current-1);update()};const next=()=>{current=Math.min(records.length-1,current+1);update()};const keys=e=>{if(e.key==='Escape')exit();if(e.key==='ArrowRight')lang==='en'?next():previous();if(e.key==='ArrowLeft')lang==='en'?previous():next()};$('#v2SlidePrev').onclick=previous;$('#v2SlideNext').onclick=next;$('#v2SlideExit').onclick=exit;document.addEventListener('keydown',keys);update()}
async function v2PPTXExport(){try{const C=window.pptxgen||window.PptxGenJS;if(!C)throw new Error('PowerPoint library missing');const pptx=new C();const landscape=v2.report.orientation!=='portrait';if(landscape)pptx.layout='LAYOUT_WIDE';else{pptx.defineLayout({name:'CP_PORTRAIT',width:7.5,height:10});pptx.layout='CP_PORTRAIT'}pptx.author='CLASS PULSE';pptx.subject='Semester report';pptx.title=v2.report.title||tr('reportTitle');pptx.lang=lang==='ar'?'ar-IL':lang==='he'?'he-IL':'en-US';const W=landscape?13.333:7.5,H=landscape?7.5:10;const rtl=lang!=='en';const recs=v2SlideRecords();recs.forEach((s,i)=>{const slide=pptx.addSlide();slide.background={color:'F8FAF6'};slide.addShape(pptx.ShapeType.rect,{x:0,y:0,w:W,h:.14,line:{color:'173A35'},fill:{color:'173A35'}});slide.addText('CLASS PULSE',{x:.55,y:.43,w:W-1,h:.33,fontFace:'Arial',fontSize:13,bold:true,color:'34765F',rtlMode:false,margin:0});slide.addShape(pptx.ShapeType.arc,{x:W-.91,y:.4,w:.36,h:.36,rotate:40,adjustPoint:.55,fill:{color:'34765F'},line:{color:'34765F'}});slide.addText(s.title,{x:.7,y:1.3,w:W-1.4,h:.8,fontFace:'Arial',fontSize:landscape?29:24,bold:true,color:'173A35',align:rtl?'right':'left',rtlMode:rtl,margin:0,breakLine:false});let bodyTop=2.35, bodyH=H-3;slide.addText(s.body,{x:.74,y:bodyTop,w:W-1.5,h:bodyH,fontFace:'Arial',fontSize:landscape?18:17,color:'345A48',align:rtl?'right':'left',rtlMode:rtl,margin:.08,breakLine:false,paraSpaceAfterPt:18, valign:'top'});if(s.kind==='grades'&&!v2.report.audience.includes('parent')){const values=s.subs.filter(x=>Number.isFinite(x.value));if(values.length){slide.addChart(pptx.ChartType.bar,[{name:tr('avg'),labels:values.map(x=>x.name),values:values.map(x=>Number(x.value.toFixed(1)))}],{x:.9,y:landscape?4.9:6.0,w:W-1.8,h:landscape?1.8:2.7,showLegend:false,showValue:true,chartColors:['34765F'],valAxisMinVal:0,valAxisMaxVal:100,catAxisLabelFontSize:10,showTitle:false,showBorder:false})}}if(s.kind==='chart'&&s.counts.some(x=>x>0)){slide.addChart(pptx.ChartType.doughnut,[{name:tr('grades'),labels:ranges.map(x=>x.label),values:s.counts}],{x:landscape?7:1.35,y:landscape?2.3:5.5,w:landscape?4.3:4.9,h:landscape?3.9:3.3,holeSize:60,showLegend:true,showValue:true,chartColors:ranges.map(x=>x.color.slice(1)),showBorder:false})}slide.addShape(pptx.ShapeType.line,{x:.65,y:H-.54,w:W-1.3,h:0,line:{color:'CFDED1',width:1}});slide.addText(`${i+1} / ${recs.length}`,{x:.68,y:H-.42,w:W-1.36,h:.2,fontFace:'Arial',fontSize:9,color:'6D8577',align:rtl?'left':'right'})});await pptx.writeFile({fileName:`CLASS_PULSE_${v2.report.audience}_${v2.report.orientation}.pptx`});message(v2tr('exportDone'))}catch(err){console.error(err);message('PPTX: '+err.message)}}
views.library=function(){return `<section class="card"><div class="v2-cardhead"><h2>${esc(v2tr('reportsLibrary'))}</h2><button class="btn" id="v2LibraryNew">＋ ${esc(v2tr('newReport'))}</button></div>${v2.library.length?`<div class="stack">${v2.library.map(x=>`<div class="v2-workitem"><div><b>${esc(x.name)}</b><small>${esc(x.date)} · ${esc(x.report.format.toUpperCase())} · ${esc(x.report.orientation)}</small></div><div class="v2-actions"><button class="btn secondary sm" data-libopen="${esc(x.id)}">${esc(v2tr('goto'))}</button><button class="btn warn sm" data-libdelete="${esc(x.id)}">${esc(tr('delete'))}</button></div></div>`).join('')}</div>`:`<p class="empty">${esc(v2tr('libraryEmpty'))}</p>`}</section>`};
const v2BindStudioBase=v2BindStudio;
