function v2BindLibrary(){$('#v2LibraryNew').onclick=()=>v2SetPage('reports');document.querySelectorAll('[data-libopen]').forEach(el=>el.onclick=()=>{const d=v2.library.find(x=>x.id===el.dataset.libopen);if(d){v2.report=structuredClone(d.report);meta.reportClass=v2.report.classId;meta.reportTerm=v2.report.term;v2.stage=3;persist();v2save();v2SetPage('reports')}});document.querySelectorAll('[data-libdelete]').forEach(el=>el.onclick=()=>{if(!confirm(tr('delete')+'?'))return;v2.library=v2.library.filter(x=>x.id!==el.dataset.libdelete);v2save();render()})}
