 en:{tag:['Student assessment and tracking platform'],user:['Username'],pass:['Password'],enter:['Sign in'],forgot:['Forgot password?'],show:['Show password'],hide:['Hide password'],required:['Please enter a username and password'],forgotMsg:['This is a demo: any password signs you in'],logout:['Sign out']}
