let v2LoginInert=[];
function v2ShowLogin(){
 if($('#cpLogin'))return;
 const x=v2LoginTx(),wrap=document.createElement('div');
 wrap.id='cpLogin';wrap.className='cp-login';wrap.dir=lang==='en'?'ltr':'rtl';
 wrap.setAttribute('role','dialog');wrap.setAttribute('aria-modal','true');wrap.setAttribute('aria-labelledby','cpLoginTitle');
 wrap.innerHTML=`<div class="cp-login-light" aria-hidden="true"></div><div class="cp-login-art">${v2LoginArt}</div><div class="cp-login-panel"><div class="cp-login-logo">${v2LoginLogo}</div><h1 id="cpLoginTitle">CLASS PULSE</h1><p class="cp-login-tag">${x.tag.map(s=>`<span>${esc(s)}</span>`).join('')}</p><form class="cp-login-form" novalidate><label class="cp-field"><input name="user" autocomplete="username" placeholder=" " required><span class="cp-field-label">${v2LoginHtml(x.user)}</span></label><label class="cp-field cp-field-pass"><input name="pass" type="password" autocomplete="current-password" placeholder=" " required><span class="cp-field-label">${v2LoginHtml(x.pass)}</span><button type="button" class="cp-eye" aria-label="${escAttr(v2LoginPlain(x.show))}" aria-pressed="false">${v2EyeIcon(true)}</button></label><p class="cp-login-msg" role="alert" hidden></p><button type="submit" class="cp-login-btn">${v2LoginHtml(x.enter)}</button><button type="button" class="cp-login-forgot">${v2LoginHtml(x.forgot)}</button></form></div>`;
 v2LoginInert=[...document.body.children].filter(el=>!el.inert);
 v2LoginInert.forEach(el=>el.inert=true);
 document.body.append(wrap);document.body.classList.add('cp-locked');
 const form=wrap.querySelector('form'),user=form.elements.user,pass=form.elements.pass,eye=wrap.querySelector('.cp-eye'),msg=wrap.querySelector('.cp-login-msg');
 const say=(text,kind)=>{msg.textContent=text;msg.className='cp-login-msg '+kind;msg.hidden=false};
 eye.onclick=()=>{const show=pass.type==='password';pass.type=show?'text':'password';eye.setAttribute('aria-pressed',String(show));eye.setAttribute('aria-label',v2LoginPlain(show?x.hide:x.show));eye.innerHTML=v2EyeIcon(!show);pass.focus()};
 wrap.querySelector('.cp-login-forgot').onclick=()=>say(v2LoginPlain(x.forgotMsg),'info');
 form.onsubmit=e=>{
  e.preventDefault();
  if(!user.value.trim()||!pass.value){say(v2LoginPlain(x.required),'error');form.classList.remove('cp-shake');void form.offsetWidth;form.classList.add('cp-shake');(user.value.trim()?pass:user).focus();return}
  v2.teacherName=user.value.trim();v2.usernameSynced=true;v2save();
  sessionStorage.setItem(v2LoginKey,'1');
  v2LoginInert.forEach(el=>el.inert=false);v2LoginInert=[];
  document.body.classList.remove('cp-locked');
  wrap.classList.add('leaving');
  setTimeout(()=>wrap.remove(),matchMedia('(prefers-reduced-motion: reduce)').matches?0:450);
 };
 user.focus();
}
function v2InitLogin(){
 const actions=$('.topbar .actions');
 if(actions&&!$('#cpLogout')){const b=document.createElement('button');b.id='cpLogout';b.className='btn secondary';b.type='button';b.onclick=()=>{sessionStorage.removeItem(v2LoginKey);v2ShowLogin()};actions.append(b)}
 if(!v2.usernameSynced)sessionStorage.removeItem(v2LoginKey);
 if(sessionStorage.getItem(v2LoginKey)!=='1')v2ShowLogin();
}
const v2LoginRender=render;
render=function(){v2LoginRender();const b=$('#cpLogout');if(b)b.textContent=v2LoginPlain(v2LoginTx().logout)};

function v2SlideRecords(){
 const d=v2ReportData(),{r,c,students,term,perSubject,gradeScores,counts,classAvg,attendance,completion}=d;
 const isParent=r.audience==='parent',person=students.find(s=>String(s.id)===String(r.studentId))||students[0];
 const enabled=new Set(r.sections||[]),title=r.title?.trim()||tr('reportTitle');
 const subjectsForSlides=perSubject.map(s=>({...s,value:isParent&&person?score(person,s.id,term):s.value}));
 const records=[];
 if(enabled.has('cover'))records.push({title,body:`${c?.school||''}\n${isParent?person?.name||'':c?.name||''} · ${v2TermLabel(term)}`,kind:'cover',coverValues:subjectsForSlides});
 if(enabled.has('stats')){
  const metrics=isParent
   ?[{label:tr('avg'),value:means(subjectsForSlides.map(s=>s.value))},{label:tr('attendance'),value:person?attPct(person.id):null,percent:true},{label:tr('completion'),value:person?completion(person.id):null,percent:true}]
   :[{label:tr('total'),value:students.length},{label:tr('avg'),value:classAvg},{label:tr('evaluated'),value:gradeScores.length}];
  records.push({title:v2SectionLabel('stats'),body:'',kind:'stats',metrics});
 }
 if(enabled.has('grades'))records.push({title:v2SectionLabel('grades'),body:'',kind:'grades',subs:subjectsForSlides});
 if(!isParent&&enabled.has('chart'))records.push({title:v2SectionLabel('chart'),body:'',kind:'chart',counts,labels:ranges.map(x=>x.label)});
 if(enabled.has('attendance')){
  records.push({title:v2SectionLabel('attendance'),body:'',kind:'attendance',metrics:[
   {label:tr('attendance'),value:isParent?(person?attPct(person.id):null):attendance,percent:true},
   {label:tr('completion'),value:isParent?(person?completion(person.id):null):completion,percent:true}
  ]});
 }
 if(!isParent&&enabled.has('trend')){
  const classId=c?.id||activeClass()?.id;
  const terms=[{label:v2TermLabel('1'),value:analyticsFor(classId,'math','1').average},{label:v2TermLabel('2'),value:analyticsFor(classId,'math','2').average}];
  records.push({title:v2SectionLabel('trend'),body:'',kind:'trend',terms});
 }
 if(enabled.has('notes'))records.push({title:v2SectionLabel('notes'),body:r.notes||tr('dataScope'),kind:'notes'});
 if(enabled.has('next'))records.push({title:v2SectionLabel('next'),body:tr('privacyNote'),kind:'next'});
 if(!records.length)records.push({title,body:tr('none'),kind:'empty'});
 return records;
}

const v2SlideRecordsWithoutTeacherNotes=v2SlideRecords;
v2SlideRecords=function(){const records=v2SlideRecordsWithoutTeacherNotes().filter(record=>record.kind!=='notes'),{r,topStudents}=v2ReportData();if(r.audience!=='parent'&&r.sections.includes('topStudents')){const index=records.findIndex(record=>record.kind==='grades');records.splice(index<0?records.length:index+1,0,{title:v2SectionLabel('topStudents'),body:'',kind:'topStudents',students:topStudents})}return records};
function v2SlideVisual(record){
 const pct=value=>Number.isFinite(value)?Math.max(0,Math.min(100,Number(value))):0;
 const metricCards=metrics=>`<div class="v2-slide-metrics">${metrics.map(m=>`<div class="v2-slide-metric"><small>${esc(m.label)}</small><strong>${esc(Number.isFinite(m.value)?fmt(m.value):'—')}${Number.isFinite(m.value)&&m.percent?'%':''}</strong></div>`).join('')}</div>`;
 if(record.kind==='cover'){
  const values=record.coverValues.filter(s=>Number.isFinite(s.value)).slice(0,4),step=284/Math.max(1,values.length),barWidth=Math.min(56,step*.62);
  const bars=values.map((s,i)=>{const h=Math.max(8,Math.min(100,pct(s.value)));const x=28+i*step+(step-barWidth)/2;return `<rect x="${x}" y="${132-h}" width="${barWidth}" height="${h}" rx="9" fill="${i===1?'#e7b866':'#49aaa0'}"/><text x="${x+barWidth/2}" y="154" text-anchor="middle">${esc(s.name)}</text>`}).join('');
  return `<div class="v2-slide-coverart"><svg viewBox="0 0 340 175" role="img" aria-label="${esc(tr('performance'))}"><path d="M12 132H328" stroke="#ffffff55" stroke-width="2"/>${bars}</svg><span>${esc(v2TermLabel(v2ReportData().term))}</span></div>`;
 }
 if(record.kind==='stats')return metricCards(record.metrics);
 if(record.kind==='topStudents')return v2TopStudentsMarkup(record.students);
 if(record.kind==='grades'){
  const values=record.subs.filter(s=>Number.isFinite(s.value));
  return values.length?`<div class="v2-slide-chart">${values.map(s=>`<div class="v2-slide-chart-row"><span>${esc(s.name)}</span><div class="v2-slide-track"><i style="width:${pct(s.value)}%"></i></div><b>${esc(fmt(s.value))}</b></div>`).join('')}</div>`:`<div class="v2-slide-empty">${esc(tr('norecord'))}</div>`;
 }
 if(record.kind==='chart'){
  const total=record.counts.reduce((sum,n)=>sum+n,0),subjectName=v2ReportData().chartSubjectName;let stop=0;
  const stops=record.counts.map((n,i)=>{const start=stop;stop+=total?100*n/total:0;return `${ranges[i].color} ${start}% ${stop}%`}).join(',');
  return `<div class="v2-slide-donut-row"><div class="v2-slide-donut" style="background:${total?`conic-gradient(${stops})`:'#e5eee7'}"><div><strong class="v2-slide-subject">${esc(subjectName)}</strong></div></div><div class="v2-slide-legend">${record.labels.map((label,i)=>`<div><i style="background:${esc(ranges[i].color)}"></i><span>${esc(label)}</span><b>${record.counts[i]}</b></div>`).join('')}</div></div>`;
 }
 if(record.kind==='attendance')return `<div class="v2-slide-metrics">${record.metrics.map(m=>`<div class="v2-slide-progress"><small>${esc(m.label)}</small><strong>${Number.isFinite(m.value)?`${esc(fmt(m.value))}%`:'—'}</strong><div class="v2-slide-track"><i style="width:${pct(m.value)}%"></i></div></div>`).join('')}</div>`;
 if(record.kind==='trend')return `<div class="v2-slide-chart">${record.terms.map(s=>`<div class="v2-slide-chart-row"><span>${esc(s.label)}</span><div class="v2-slide-track"><i style="width:${pct(s.value)}%"></i></div><b>${esc(fmt(s.value))}</b></div>`).join('')}</div>`;
 return '';
}

function v2Present(){
 const records=v2SlideRecords();let current=0;
 const previousOverflow=document.body.style.overflow;document.body.style.overflow='hidden';
 const overlay=document.createElement('div');overlay.className='v2-slideview';overlay.id='v2SlideView';
 overlay.innerHTML=`<div class="v2-presentation"><div class="v2-slideframe" dir="${transText()}"><div class="v2-slidebrand">CLASS PULSE <span>· PROGRESS CIRCLE</span></div><h2 id="v2SlideTitle"></h2><div class="v2-slide-layout"><div class="v2-slide-copy"><p id="v2SlideText"></p></div><div class="v2-slide-visual" id="v2SlideVisual"></div></div><div class="v2-slide-footer"><span>${esc(v2ReportData().c?.name||'CLASS PULSE')}</span><span id="v2SlideCount" dir="ltr"></span></div></div><div class="v2-slidecontrols"><button id="v2SlidePrev">${esc(v2tr('prevSlide'))}</button><button id="v2SlideNext">${esc(v2tr('nextSlide'))}</button><button id="v2SlideExit">${esc(v2tr('closeSlides'))}</button></div></div>`;
 document.body.append(overlay);
 const frame=overlay.querySelector('.v2-slideframe'),title=$('#v2SlideTitle'),text=$('#v2SlideText'),visual=$('#v2SlideVisual');
 const update=()=>{const record=records[current];title.textContent=record.title;text.textContent=record.body;visual.innerHTML=v2SlideVisual(record);frame.classList.toggle('is-cover',record.kind==='cover');frame.dataset.kind=record.kind;$('#v2SlideCount').textContent=`${current+1} / ${records.length}`;$('#v2SlidePrev').disabled=current===0;$('#v2SlideNext').disabled=current===records.length-1};
 const exit=()=>{overlay.remove();document.body.style.overflow=previousOverflow;document.removeEventListener('keydown',keys)};
 const previous=()=>{current=Math.max(0,current-1);update()},next=()=>{current=Math.min(records.length-1,current+1);update()};
 const keys=e=>{if(e.key==='Escape')exit();if(e.key==='ArrowRight')lang==='en'?next():previous();if(e.key==='ArrowLeft')lang==='en'?previous():next()};
 $('#v2SlidePrev').onclick=previous;$('#v2SlideNext').onclick=next;$('#v2SlideExit').onclick=exit;
 document.addEventListener('keydown',keys);update();
}

async function v2PPTXExport(){
 try{
  const C=window.pptxgen||window.PptxGenJS;if(!C)throw new Error('PowerPoint library missing');
  const pptx=new C(),landscape=v2.report.orientation!=='portrait';
  if(landscape)pptx.layout='LAYOUT_WIDE';else{pptx.defineLayout({name:'CP_PORTRAIT',width:7.5,height:10});pptx.layout='CP_PORTRAIT'}
  pptx.author='CLASS PULSE';pptx.subject='Semester report';pptx.title=v2.report.title||tr('reportTitle');pptx.lang=lang==='ar'?'ar-IL':lang==='he'?'he-IL':'en-US';
  const W=landscape?13.333:7.5,H=landscape?7.5:10,rtl=lang!=='en',margin=.68;
  const colors={deep:'123E47',teal:'168B8D',green:'34765F',ink:'20352F',muted:'647E70',paper:'F6F9F4',line:'DCE9DF',white:'FFFFFF'};
  const text=(slide,value,opts={})=>slide.addText(String(value??''),{fontFace:'Arial',color:colors.ink,margin:0,align:rtl?'right':'left',rtlMode:rtl,...opts});
  const addFooter=(slide,i)=>{slide.addShape(pptx.ShapeType.rect,{x:margin,y:H-.56,w:W-margin*2,h:.012,line:{color:colors.line},fill:{color:colors.line}});text(slide,'CLASS PULSE · LEARNING REPORT',{x:margin,y:H-.43,w:W/2,h:.18,fontSize:8,color:colors.muted,align:rtl?'right':'left'});text(slide,`${i+1} / ${recs.length}`,{x:W-margin-1,y:H-.43,w:1,h:.18,fontSize:8,color:colors.muted,align:rtl?'left':'right',rtlMode:false})};
  const addMetricCards=(slide,metrics,y)=>{const gap=.18,w=(W-margin*2-gap*(metrics.length-1))/metrics.length,h=1.95;metrics.forEach((m,i)=>{const x=margin+i*(w+gap);slide.addShape(pptx.ShapeType.rect,{x,y,w,h,line:{color:colors.line,width:1},fill:{color:colors.white}});slide.addShape(pptx.ShapeType.rect,{x,y,w:.07,h,line:{color:colors.teal},fill:{color:colors.teal}});text(slide,m.label,{x:x+.18,y:y+.3,w:w-.36,h:.38,fontSize:landscape?12:10,color:colors.muted});text(slide,Number.isFinite(m.value)?`${fmt(m.value)}${m.percent?'%':''}`:'—',{x:x+.18,y:y+.86,w:w-.36,h:.55,fontSize:landscape?25:20,bold:true,color:colors.deep})})};
  const recs=v2SlideRecords();
  recs.forEach((s,i)=>{
   const slide=pptx.addSlide(),isCover=s.kind==='cover';slide.background={color:isCover?colors.deep:colors.paper};
   if(isCover){
    slide.addShape(pptx.ShapeType.rect,{x:0,y:0,w:.17,h:H,line:{color:colors.teal},fill:{color:colors.teal}});
    slide.addShape(pptx.ShapeType.ellipse,{x:W-4.4,y:.65,w:3.2,h:3.2,line:{color:'2A7167',transparency:35,width:10},fill:{color:colors.deep,transparency:100}});
    text(slide,'CLASS PULSE  ·  PROGRESS CIRCLE',{x:margin,y:.62,w:W-2*margin,h:.34,fontSize:12,bold:true,color:'B8E5D2',rtlMode:false});
    text(slide,s.title,{x:margin,y:2.05,w:W*.7,h:1.55,fontSize:landscape?38:29,bold:true,color:colors.white,breakLine:false});
    text(slide,s.body,{x:margin,y:3.92,w:W*.7,h:1.05,fontSize:landscape?18:15,color:'D3E8DD',breakLine:false,valign:'top'});
    const vals=(s.coverValues||[]).filter(x=>Number.isFinite(x.value)).slice(0,4),step=3.68/Math.max(1,vals.length);
    vals.forEach((x,j)=>{const bh=Math.max(.15,Math.min(1.75,Number(x.value)/100*1.75)),bx=W-4.15+j*step;slide.addShape(pptx.ShapeType.rect,{x:bx,y:5.7-bh,w:Math.min(.58,step*.62),h:bh,line:{color:j===1?'E7B866':colors.teal},fill:{color:j===1?'E7B866':colors.teal}});text(slide,x.name,{x:bx-.1,y:5.82,w:.8,h:.35,fontSize:8,color:'D3E8DD',align:'center',rtlMode:false})});
    addFooter(slide,i);return;
   }
   slide.addShape(pptx.ShapeType.rect,{x:0,y:0,w:W,h:.13,line:{color:colors.teal},fill:{color:colors.teal}});
   text(slide,'CLASS PULSE  /  LEARNING REPORT',{x:margin,y:.42,w:W-2*margin,h:.28,fontSize:10,bold:true,color:colors.green,rtlMode:false});
   text(slide,s.title,{x:margin,y:1.05,w:W-2*margin,h:.72,fontSize:landscape?28:23,bold:true,color:colors.deep,breakLine:false});
   if(s.kind==='stats')addMetricCards(slide,s.metrics,2.65);
   if(s.kind==='grades'){
    const values=s.subs.filter(x=>Number.isFinite(x.value));
    if(values.length)slide.addChart(pptx.ChartType.bar,[{name:tr('avg'),labels:values.map(x=>x.name),values:values.map(x=>Number(x.value.toFixed(1)))}],{x:margin,y:2.25,w:W-margin*2,h:H-3.15,barDir:'bar',showLegend:false,showValue:true,showTitle:false,showBorder:false,chartColors:[colors.teal],valAxisMinVal:0,valAxisMaxVal:100,catAxisLabelFontFace:'Arial',valAxisLabelFontFace:'Arial',catAxisLabelFontSize:11,valAxisLabelFontSize:9});
    else text(slide,tr('norecord'),{x:margin,y:2.7,w:W-margin*2,h:.5,fontSize:16,color:colors.muted});
   }
   if(s.kind==='topStudents'){
    if(s.students.length){
     const gap=.16,w=(W-margin*2-gap*2)/3,cardH=Math.min(5.8,H-4),positions=[{student:s.students[1],rank:2,x:margin,y:2.65,h:cardH},{student:s.students[0],rank:1,x:margin+w+gap,y:2.4,h:cardH+.5},{student:s.students[2],rank:3,x:margin+2*(w+gap),y:2.65,h:cardH}];
     positions.forEach(({student,rank,x,y,h})=>{if(!student)return;const first=rank===1,accent=first?'E7B866':'74A995';slide.addShape(pptx.ShapeType.rect,{x,y,w,h,line:{color:first?'E7B866':colors.line,width:first?2:1},fill:{color:colors.white}});slide.addShape(pptx.ShapeType.ellipse,{x:x+w/2-.23,y:y+.24,w:.46,h:.46,line:{color:accent},fill:{color:accent}});text(slide,String(rank),{x:x+w/2-.18,y:y+.35,w:.36,h:.18,fontSize:12,bold:true,color:colors.white,align:'center',rtlMode:false});text(slide,v2tr(['rankFirst','rankSecond','rankThird'][rank-1]),{x:x+.1,y:y+.86,w:w-.2,h:.35,fontSize:landscape?11:9,bold:true,color:colors.muted,align:'center',rtlMode:false,fit:'shrink'});text(slide,student.name,{x:x+.1,y:y+1.3,w:w-.2,h:.65,fontSize:landscape?17:13,bold:true,color:colors.deep,align:'center',rtlMode:rtl,fit:'shrink',valign:'mid'});text(slide,fmt(student.average),{x:x+.1,y:y+2.03,w:w-.2,h:.45,fontSize:landscape?24:19,bold:true,color:first?'A97519':colors.teal,align:'center',rtlMode:false});text(slide,v2tr('topAverage'),{x:x+.1,y:y+2.53,w:w-.2,h:.3,fontSize:landscape?9:8,color:colors.muted,align:'center',rtlMode:false,fit:'shrink'})});
    }else text(slide,v2tr('noTopStudents'),{x:margin,y:2.7,w:W-margin*2,h:.5,fontSize:16,color:colors.muted});
   }
   if(s.kind==='chart'&&s.counts.some(x=>x>0)){
    const chartW=landscape?6:4,chartH=H-3,chartX=rtl?W-margin-chartW:margin,chartY=2.1,legendW=landscape?3.8:1.9,legendX=rtl?margin:chartX+chartW+.2,legendY=chartY+chartH/2-s.labels.length*.38/2;
    slide.addChart(pptx.ChartType.doughnut,[{name:tr('grades'),labels:s.labels,values:s.counts}],{x:chartX,y:chartY,w:chartW,h:chartH,holeSize:62,showLegend:false,showValue:true,showPercent:true,showTitle:false,showBorder:false,chartColors:ranges.map(x=>x.color.replace('#',''))});
    const subjectName=v2ReportData().chartSubjectName;
    slide.addText(subjectName,{x:chartX+chartW/2-.9,y:chartY+chartH/2-.16,w:1.8,h:.32,fontFace:'Arial',fontSize:10,color:colors.deep,align:'center',valign:'mid',fit:'shrink',margin:0,breakLine:false});
    s.labels.forEach((label,index)=>{const y=legendY+index*.38,color=ranges[index].color.replace('#','');slide.addShape(pptx.ShapeType.rect,{x:legendX,y:y+.06,w:.13,h:.13,line:{color},fill:{color}});text(slide,`${label}  ${s.counts[index]}`,{x:legendX+.2,y,w:legendW-.2,h:.25,fontSize:10,color:colors.ink,breakLine:false,fit:'shrink'})});
   }
   if(s.kind==='attendance'){
    const gap=.3,w=(W-margin*2-gap)/2,y=2.55,h=2.55;
    s.metrics.forEach((m,j)=>{const x=margin+j*(w+gap),value=Number.isFinite(m.value)?Math.max(0,Math.min(100,m.value)):0;slide.addShape(pptx.ShapeType.rect,{x,y,w,h,line:{color:colors.line,width:1},fill:{color:colors.white}});text(slide,m.label,{x:x+.22,y:y+.35,w:w-.44,h:.35,fontSize:13,color:colors.muted});text(slide,Number.isFinite(m.value)?`${fmt(m.value)}%`:'—',{x:x+.22,y:y+.86,w:w-.44,h:.62,fontSize:landscape?31:25,bold:true,color:colors.deep});slide.addShape(pptx.ShapeType.rect,{x:x+.22,y:y+1.78,w:w-.44,h:.16,line:{color:'E7EEE8'},fill:{color:'E7EEE8'}});slide.addShape(pptx.ShapeType.rect,{x:x+.22,y:y+1.78,w:(w-.44)*value/100,h:.16,line:{color:colors.teal},fill:{color:colors.teal}})});
   }
   if(s.kind==='trend'){const terms=s.terms.filter(x=>Number.isFinite(x.value));if(terms.length)slide.addChart(pptx.ChartType.bar,[{name:tr('avg'),labels:terms.map(x=>x.label),values:terms.map(x=>Number(x.value.toFixed(1)))}],{x:margin+.35,y:2.3,w:W-margin*2-.7,h:H-3.2,barDir:'col',showLegend:false,showValue:true,showTitle:false,showBorder:false,chartColors:[colors.green],valAxisMinVal:0,valAxisMaxVal:100,catAxisLabelFontFace:'Arial',valAxisLabelFontFace:'Arial',catAxisLabelFontSize:12})}
   if(['notes','next','empty'].includes(s.kind))text(slide,s.body,{x:margin,y:2.15,w:W-margin*2,h:H-3.15,fontSize:landscape?20:17,color:colors.ink,valign:'top',breakLine:false,fit:'shrink'});
   addFooter(slide,i);
  });
  await pptx.writeFile({fileName:`CLASS_PULSE_${v2.report.audience}_${v2.report.orientation}.pptx`});
  message(v2tr('exportDone'));
 }catch(err){console.error(err);message('PPTX: '+err.message)}
}

const v2ReportsViewBase=views.reports;
views.reports=function(){let html=v2ReportsViewBase();if(v2.stage===1){const r=v2CurrentReport(),last=r.sections.length-1;html=html.replace('<button data-move="up" data-index="0"','<button data-move="up" data-index="0" disabled');if(last>=0)html=html.replace(`<button data-move="down" data-index="${last}"`,`<button data-move="down" data-index="${last}" disabled`);if(v2SectionIds.every(id=>r.sections.includes(id)))html=html.replace('id="v2RestoreSection"','id="v2RestoreSection" disabled')}return html};

